#!/usr/bin/env bash
# Generate the feature-demo comparison and git repository for emeld.
#
# Usage: test/make-example.sh [OUTPUT-DIR]   (default: test/example)
#
# OUTPUT-DIR gets left/ and right/ (the comparison) and git-repo/ (a small
# repository for the git-mode walkthroughs).  The output is gitignored: this
# generator, not the generated bytes, is the source of truth.  Contents and
# mtimes are deterministic, so demo trees (and the videos recorded from
# them) are reproducible.  See test/README.org for the walkthrough recipes.
set -e
SELF="$(cd "$(dirname "$0")" && pwd)"
EMELD_DIR="$(cd "$SELF/.." && pwd)"
OUT="${1:-$SELF/example}"

exec emacs -Q --batch -L "$EMELD_DIR" -l emeld.el -l "$SELF/emeld-example.el" \
    --eval "(let ((manifest (emeld-example-make \"$OUT\")))
              (emeld-example-make-git \"$OUT/git-repo\")
              (princ (format \"Generated %s: %d changed file(s); git demo in %s/git-repo\\n\"
                             \"$OUT\" (length manifest) \"$OUT\")))"
